-- 574: Original BrillaPrep WASSCE English Language sprint 3 beta questions, part 4 of 9 (batch wassce-english-sprint3-001).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_574_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_574_guard;
INSERT INTO _migration_574_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_001' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_cmp' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "When the pipe-borne water failed in Nkwanta, the women rose before dawn to queue at the only borehole. Efua carried two jerrycans on her head and her baby on her back. Then the assemblyman had a second borehole drilled, and the queues grew shorter. "Water is life," Efua said, "but so is the time we lose fetching it."" Why did the women of Nkwanta rise before dawn?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. to queue at the only borehole","B. to sell wares at the market","C. to attend assembly at the school","D. to fetch firewood for cooking"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The first sentence says the women "rose before dawn to queue at the only borehole" when the pipe-borne water failed; the market, an assembly and firewood are never mentioned. Therefore the correct answer is A: to queue at the only borehole.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_001' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_574_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_006' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_cmp' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "When the pipe-borne water failed in Nkwanta, the women rose before dawn to queue at the only borehole. Efua carried two jerrycans on her head and her baby on her back. Then the assemblyman had a second borehole drilled, and the queues grew shorter. "Water is life," Efua said, "but so is the time we lose fetching it."" The passage suggests the water shortage burdened mainly' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. the schoolchildren","B. the women, who did the fetching","C. the assemblyman","D. the lorry drivers"]' AND q.correct_answer IS 'B' AND q.explanation IS 'It is the women who rise before dawn to queue, and Efua fetches while carrying her baby; schoolchildren, the assemblyman and drivers are not shown bearing the load. Therefore the correct answer is B: the women, who did the fetching.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Infer' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_006' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_574_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_009' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_cmp' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "Zebilla Senior High reached the regional debating finals. Coach Adongo insisted that facts must be clothed in courtesy. On the day, their opponents spoke louder, but Zebilla spoke better: every claim was supported, every rebuttal polite. The verdict was unanimous, and the trophy rode home on the captain''s knees like a baby." The trophy "rode home on the captain''s knees like a baby". This simile suggests the trophy was' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. handled with great care and pride","B. too heavy for one person to lift","C. damaged on the journey home","D. of little value to the team"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Holding the trophy "like a baby" conveys tenderness and pride: the team treasured it. Nothing suggests it was too heavy, damaged or unvalued. Therefore the correct answer is A: handled with great care and pride.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Interpret' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_009' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_574_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_028' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_sum' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Choose the best summary of the following. — "Although the harvest was good, the farmers earned little, for the middlemen who bought the produce paid very low prices."' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The middlemen had a good harvest and paid the farmers well.","B. The farmers earned little because the harvest failed.","C. The middlemen earned little although the farmers harvested well.","D. Despite a good harvest, the farmers earned little because middlemen paid low prices."]' AND q.correct_answer IS 'D' AND q.explanation IS 'The correct option keeps all three ideas — good harvest, low earnings, low prices from the middlemen — in their proper relationships; the others swap the actors or reverse the facts. Therefore the correct answer is D: Despite a good harvest, the farmers earned little because middlemen paid low prices..' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Summarize' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_028' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_eng_s3_001', 'topic_wassce_p2_eng_cmp', 'subj_wassce_english', 'exam_wassce', NULL, NULL, 'Read the passage, then answer. — "When the pipe-borne water failed in Nkwanta, the women rose before dawn to queue at the only borehole. Efua carried two jerrycans on her head and her baby on her back. Then the assemblyman had a second borehole drilled, and the queues grew shorter. "Water is life," Efua said, "but so is the time we lose fetching it."" Why did the women of Nkwanta rise before dawn?', 'multiple_choice', NULL, '["A. to queue at the only borehole","B. to sell wares at the market","C. to attend assembly at the school","D. to fetch firewood for cooking"]', 'A', 'The first sentence says the women "rose before dawn to queue at the only borehole" when the pipe-borne water failed; the market, an assembly and firewood are never mentioned. Therefore the correct answer is A: to queue at the only borehole.', 'easy', '3', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL);
